function kthSmallest(root, k) {
  const stack = [];
  let current = root;
  while (current !== null || stack.length > 0) {
    while (current !== null) {
      stack.push(current);
      current = current.left;
    }
    current = stack.pop();
    k--;
    if (k === 0) return current.key;
    current = current.right;
  }
  return undefined;
}

