function floor(root, weight) {
  let best = null;
  let current = root;
  while (current !== null) {
    if (current.key === weight) return current;
    if (current.key < weight) {
      best = current;
      current = current.right;
    } else {
      current = current.left;
    }
  }
  return best;
}

